package rentalpropertymanagementapp.be.Controller;
import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import rentalpropertymanagementapp.be.DTO.*;import rentalpropertymanagementapp.be.Service.AnnouncementResourceService;import java.util.*;
@RestController @RequestMapping("/be/announcements") public class AnnouncementController {private final AnnouncementResourceService service;public AnnouncementController(AnnouncementResourceService service){this.service=service;}@GetMapping public List<AnnouncementResponse> list(){return service.list().stream().map(service::response).toList();}@PostMapping @ResponseStatus(HttpStatus.CREATED) public AnnouncementResponse create(@Valid @RequestBody AnnouncementRequest request){return service.response(service.save(null,request));}@PutMapping("/{id}") public AnnouncementResponse update(@PathVariable UUID id,@Valid @RequestBody AnnouncementRequest request){return service.response(service.save(id,request));}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable UUID id){service.delete(id);return ResponseEntity.noContent().build();}}
